# SaleHop update: crowdsourced "spotted a sale" reporting
# - Anyone browsing the Map screen can now tap a new "🚩 Spot a Sale"
#   button to report a garage sale they just drove past -- no account
#   needed. That captures their current GPS location (never a public
#   address) and either starts a new report or, if it's close to an
#   existing unconfirmed one, adds to it.
# - A spotted sale becomes "confirmed" (and gets a solid teal pin instead
#   of a dashed amber one) one of two ways:
#     1. "Crowd" -- enough different people report the same spot
#        (spotted_sale_confirm_count in /admin, default 3). One anonymous
#        per-browser device id can only count once toward this, so a
#        single person tapping it repeatedly can't fake the threshold.
#     2. "Visit" -- while someone is on the Map screen and their live
#        location comes within the same-sale radius of an unconfirmed
#        spot, the app shows an in-app "Are you here?" prompt; tapping
#        "Yes, I found it" grabs their precise current location, which
#        replaces the original (likely rougher, reported from a moving
#        car) location.
#   This is in-app only, not a background push notification -- it only
#   ever fires while the Map screen is actually open on screen.
# - Unconfirmed spots still show on the map (dashed amber pin + a
#   disclaimer in their popup) so someone else can go verify them --
#   that's what makes the confirm-by-visit path possible at all. An old
#   report that never gets enough interest quietly stops showing after 3
#   days; a confirmed one doesn't auto-expire (same as regular listings).
# - New /admin "Spotted Sales" section: a settings panel for the same-sale
#   radius and confirm-count (same pattern as the existing Ad Frequency
#   panel), plus a list of every report with Approve/Reject/Delete. Only
#   the aggregate report count is ever shown -- individual reporters stay
#   confidential, even from /admin.
# - New file: supabase/schema-v10-spotted-sales.sql (new `spotted_sales`
#   table + two new `app_settings` columns -- run this once in the
#   Supabase SQL Editor). New files: lib/deviceId.js, the four new API
#   routes under app/api/spotted-sales and app/api/admin/spotted-sales.
#   Touches app/api/admin/settings/route.js, components/AppShell.js,
#   components/MapScreen.js, components/LeafletMap.js, app/admin/page.js,
#   and app/globals.css. No new npm package.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

